head.b:skin:
/* ============ TOOLS PRO WEB - Royal Blue 2026 ============ */
:root{
  --royal: #2563EB;
  --royal-deep: #1D4ED8;
  --royal-dark: #1E3A8A;
  --electric: #3B82F6;
  --sky-blue: #60A5FA;
  --blue-light: #DBEAFE;
  --blue-soft: #EFF6FF;
  --navy: #0F172A;
  --dark-bg: #0B1220;
  --blue-glow: rgba(37, 99, 235, 0.25);

  --text: var(--ink);
  --text-secondary: var(--muted);
  --text-muted: var(--muted);
  --border: var(--line);
  --surface: var(--card);
  --surface-2: var(--sky);
  --bg-alt: var(--sky);
  --brand: var(--tpw-primary);
  --brand-soft: #DBEAFE;
  --brand-light: #60A5FA;
  --brand-dark: #1E3A8A;
  --secondary: var(--tpw-dark-bg);
  --neutral: #6B7385;
  --muted: #52628A;
  --bg: var(--tpw-blue-soft);
  --card: #FFFFFF;
  --sky: #F4F7FE;
  --ink: var(--tpw-navy);
  --line: #DEE6F8;
  --chip: #FFFFFF;
  --shadow: 0 10px 32px var(--tpw-blue-glow);
  --shadow-lg: 0 20px 55px var(--tpw-blue-glow);
  --grad: linear-gradient(135deg,var(--tpw-primary-dark) 0%,var(--tpw-primary) 35%,var(--tpw-blue) 68%,var(--tpw-sky) 100%);
  --radius: 18px;
  --radius-sm: 12px;
  --transition: 0.22s ease;

  --tpw-primary: #2563EB;
  --tpw-primary-hover: #1D4ED8;
  --tpw-primary-dark: #1E3A8A;
  --tpw-blue: #3B82F6;
  --tpw-sky: #60A5FA;
  --tpw-blue-light: #DBEAFE;
  --tpw-blue-soft: #EFF6FF;
  --tpw-navy: #0F172A;
  --tpw-dark-bg: #0B1220;
  --tpw-blue-glow: rgba(37, 99, 235, 0.25);
}
[data-theme="dark"]{
  --royal: #2563EB;
  --royal-deep: #1D4ED8;
  --royal-dark: #1E3A8A;
  --electric: #3B82F6;
  --sky-blue: #60A5FA;
  --blue-light: #DBEAFE;
  --blue-soft: #EFF6FF;
  --navy: #0F172A;
  --dark-bg: #0B1220;
  --blue-glow: rgba(37, 99, 235, 0.25);

  --brand-soft: rgba(96,148,255,.16);
  --brand-light: #8AB0FF;
  --brand-dark: #1E3A8A;
  --bg: #050A1A;
  --card: #0D1830;
  --sky: #101D38;
  --ink: #EAF1FF;
  --muted: #92A6D6;
  --line: #1D2C55;
  --chip: #10193A;
  --shadow: 0 10px 32px rgba(0,0,0,.5);
  --shadow-lg: 0 22px 60px rgba(0,0,0,.65);

  --tpw-primary: #2563EB;
  --tpw-primary-hover: #1D4ED8;
  --tpw-primary-dark: #1E3A8A;
  --tpw-blue: #3B82F6;
  --tpw-sky: #60A5FA;
  --tpw-blue-light: #DBEAFE;
  --tpw-blue-soft: #EFF6FF;
  --tpw-navy: #0F172A;
  --tpw-dark-bg: #0B1220;
  --tpw-blue-glow: rgba(37, 99, 235, 0.25);
}
html{color-scheme: light}
[data-theme="dark"]{color-scheme: dark}
body{transition:background-color .25s ease,color .25s ease}
*{-webkit-box-sizing:border-box;box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth;scrollbar-color:#2563EB #EFF6FF}
::-webkit-scrollbar{width:10px}
::-webkit-scrollbar-track{background:#EFF6FF;border-radius:10px}
::-webkit-scrollbar-thumb{background:#2563EB;border-radius:10px;border:2px solid #EFF6FF}
body{font-family:'Manrope',sans-serif;background:var(--bg);color:var(--ink);overflow-x:hidden;line-height:1.6;min-width:280px;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
h1,h2,h3,.brand,.stat-num{font-family:'Sora',sans-serif}
a{text-decoration:none;color:inherit}
button{border:none;background:none;cursor:pointer;font-family:inherit}
img,svg,video,canvas{max-width:100%}
button,input,select,textarea{font:inherit}
:where(a,button,input,select,textarea,[tabindex]):focus-visible{outline:3px solid var(--sky-blue);outline-offset:3px}
::selection{background:var(--royal);color:#fff}

/* Header */
header.tpw-header{position:sticky;top:0;z-index:100;background:var(--grad);color:#fff;border-bottom:1px solid rgba(255,255,255,.18);-webkit-backdrop-filter:saturate(1.2) blur(10px);backdrop-filter:saturate(1.2) blur(10px);-webkit-transition:box-shadow .3s ease;transition:box-shadow .3s ease}
header.tpw-header.scrolled{box-shadow:0 12px 34px rgba(8,20,64,.28)}
.header-inner{max-width:1280px;margin:0 auto;display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;justify-content:space-between;gap:16px;padding:13px 24px;position:relative}
.header-inner.scrolled{box-shadow:0 12px 34px rgba(8,20,64,.28)}
.header-search{position:relative;-webkit-box-flex:1;-ms-flex:1 1 500px;flex:1 1 500px;max-width:500px;min-width:200px;transition:all .3s ease;order:2;margin:0 auto}
.logo{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;gap:11px;-ms-flex-negative:0;flex-shrink:0;min-width:0;order:1}
.tpw-logo-slot{min-width:0;justify-self:start;order:1;display:flex;align-items:center}.tpw-logo-slot .widget,.tpw-logo-slot .widget-content{margin:0;padding:0;min-width:0;display:flex;align-items:center}.tpw-logo-slot h2{display:none}
.tpw-logo-slot img.logo-image{--tpw-logo-width:160px;display:block !important;width:var(--tpw-logo-width) !important;min-width:0 !important;max-width:100% !important;height:auto !important;max-height:54px !important;aspect-ratio:320/107;object-fit:contain;object-position:left center;background:transparent !important;mix-blend-mode:normal !important;-ms-flex-negative:0;flex-shrink:0}
footer.tpw-footer img.footer-logo-image{--tpw-footer-logo-width:160px;display:block;width:var(--tpw-footer-logo-width) !important;min-width:0 !important;max-width:100% !important;height:auto !important;max-height:54px !important;aspect-ratio:320/107;object-fit:contain;object-position:left center;background:transparent !important;mix-blend-mode:normal !important;-ms-flex-negative:0;flex-shrink:0}
.foot-about > a.logo{width:160px;max-width:100%;padding:0;opacity:1;overflow:hidden}
.logo-badge{width:42px;height:42px;border-radius:13px;background:linear-gradient(150deg,rgba(255,255,255,.28),rgba(255,255,255,.1));display:grid;place-items:center;box-shadow:inset 0 1px 0 rgba(255,255,255,.35),0 4px 14px rgba(0,0,0,.12);border:1px solid rgba(255,255,255,.3);-webkit-transition:transform .25s ease;transition:transform .25s ease}
.logo:hover .logo-badge{transform:scale(1.05) rotate(-4deg)}
.logo-badge svg{display:block}
.logo-text{font-family:'Sora';font-weight:800;font-size:1.1rem;line-height:1.12;color:#fff;white-space:nowrap;letter-spacing:-.01em}
.logo-text span{display:block;font-size:.6rem;font-weight:700;letter-spacing:.15em;color:rgba(255,255,255,.78);text-transform:uppercase;margin-top:1px}
.header-search input{width:100%;padding:12px 46px 12px 46px;border:1.5px solid rgba(255,255,255,.3);border-radius:50px;background:rgba(255,255,255,.12);color:#fff;font:600 .92rem 'Manrope';outline:none;-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);transition:border-color .25s ease, background .25s ease, box-shadow .25s ease}
.search-arrow{position:absolute;right:7px;top:50%;-webkit-transform:translateY(-50%);transform:translateY(-50%);width:34px;height:34px;border-radius:50%;display:grid;place-items:center;color:rgba(255,255,255,.82);cursor:pointer;transition:all .25s ease;z-index:3}
.search-arrow:hover{background:rgba(255,255,255,.18);color:#fff}
.search-arrow svg{width:18px;height:18px;transition:transform .3s ease}
.search-arrow.open svg{-webkit-transform:rotate(180deg);transform:rotate(180deg)}
.header-search input::-webkit-input-placeholder{color:rgba(255,255,255,.7)}
.header-search input::placeholder{color:rgba(255,255,255,.7)}
.header-search input:focus{border-color:rgba(255,255,255,.85);background:rgba(255,255,255,.2);box-shadow:0 0 0 4px rgba(255,255,255,.14),0 6px 20px rgba(0,0,0,.1)}
.header-search > svg{position:absolute;left:16px;top:50%;-webkit-transform:translateY(-50%);transform:translateY(-50%);width:18px;height:18px;stroke:rgba(255,255,255,.8);pointer-events:none;-webkit-transition:stroke .25s ease;transition:stroke .25s ease}
.header-search:focus-within > svg{stroke:#fff}
.search-dropdown{position:absolute;top:calc(100% + 10px);left:0;right:0;background:var(--card);border:1.5px solid var(--line);border-radius:16px;-webkit-box-shadow:var(--shadow-lg);box-shadow:var(--shadow-lg);max-height:384px;overflow-y:auto;overflow-x:hidden;z-index:999;display:none;text-align:left;-webkit-overflow-scrolling:touch}
.search-dropdown.show{display:block}
.search-item{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;gap:10px;padding:10px 14px;cursor:pointer;-webkit-transition:background .2s ease;transition:background .2s ease}
.search-item:hover{background:var(--blue-soft)}
.search-item:first-child{border-radius:16px 16px 0 0}
.search-item:last-child{border-radius:0 0 16px 16px}
.search-item .tool-ico{width:32px;height:32px;-ms-flex-negative:0;flex-shrink:0}
.search-item-info{-webkit-box-flex:1;-ms-flex:1;flex:1;min-width:0}
.search-item-name{font-size:.88rem;font-weight:700;color:var(--ink);font-family:'Manrope'}
.search-item-cat{font-size:.75rem;color:var(--muted);margin-top:1px}
.search-empty{padding:20px;text-align:center;color:var(--muted);font-size:.88rem;font-weight:600}
.search-chips{display:-webkit-box;display:-ms-flexbox;display:flex;gap:6px;padding:10px 12px 8px;overflow-x:auto;scrollbar-width:none;position:sticky;top:0;background:var(--card);z-index:2;border-bottom:1px solid var(--line)}
.search-chips::-webkit-scrollbar{display:none}
.search-chip{-ms-flex-negative:0;flex-shrink:0;padding:6px 13px;border-radius:50px;border:1px solid var(--line);background:var(--bg);color:var(--muted);font:700 .76rem 'Manrope';white-space:nowrap;cursor:pointer;transition:all .2s ease}
.search-chip:hover{border-color:var(--royal);color:var(--royal)}
.search-chip.active{background:var(--grad);color:#fff;border-color:transparent;-webkit-box-shadow:0 4px 12px rgba(37,99,235,.3);box-shadow:0 4px 12px rgba(37,99,235,.3)}
.search-item mark{background:rgba(37,99,235,.14);color:var(--royal-deep);border-radius:4px;padding:0 3px;font-weight:800}
[data-theme="dark"] .search-item mark{background:rgba(96,165,250,.24);color:#93C5FD}
.search-item.active{background:#EFF6FF;border-left:3px solid var(--royal);-webkit-box-shadow:inset 0 0 0 1px rgba(37,99,235,.15);box-shadow:inset 0 0 0 1px rgba(37,99,235,.15)}
.search-item.active .search-item-name{color:var(--royal-dark)}
.search-item.active .search-item-cat{color:var(--royal);font-weight:600}
.search-item.active mark{background:rgba(37,99,235,.22);color:var(--royal-dark);border-radius:4px;padding:0 3px;font-weight:800}
[data-theme="dark"] .search-item:hover{background:rgba(37,99,235,.15)}
[data-theme="dark"] .search-item.active{background:rgba(37,99,235,.28);border-left:3px solid var(--sky-blue);-webkit-box-shadow:inset 0 0 0 1px rgba(96,165,250,.25);box-shadow:inset 0 0 0 1px rgba(96,165,250,.25)}
[data-theme="dark"] .search-item.active .search-item-name{color:#fff}
[data-theme="dark"] .search-item.active .search-item-cat{color:var(--sky-blue);font-weight:600}
[data-theme="dark"] .search-item.active mark{background:rgba(96,165,250,.38);color:#DBEAFE}
.search-related{border-top:1px solid var(--line);padding:10px 12px 12px;background:var(--sky)}
.search-related-title{font:800 .72rem 'Manrope';letter-spacing:.06em;text-transform:uppercase;color:var(--muted);margin-bottom:7px}
.search-related-links{display:-webkit-box;display:-ms-flexbox;display:flex;gap:7px;overflow-x:auto;scrollbar-width:none}
.search-related-links::-webkit-scrollbar{display:none}
.search-related-link{flex:0 0 auto;max-width:190px;padding:7px 11px;border-radius:10px;background:var(--card);border:1px solid var(--line);color:var(--ink);font-size:.78rem;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.search-related-link:hover{border-color:var(--royal);color:var(--royal)}
.search-section-title{padding:10px 14px 5px;font:800 .7rem 'Manrope';letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}
.search-recent{display:-webkit-box;display:-ms-flexbox;display:flex;-ms-flex-wrap:wrap;flex-wrap:wrap;gap:8px;padding:2px 14px 12px}
.search-recent .sr{padding:7px 13px;border-radius:50px;background:var(--bg);border:1px solid var(--line);font:700 .82rem 'Manrope';color:var(--ink);cursor:pointer;transition:all .2s ease;display:-webkit-inline-box;display:-ms-inline-flexbox;display:inline-flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;gap:6px}
.search-recent .sr:hover{border-color:var(--royal);color:var(--royal);-webkit-transform:translateY(-2px);transform:translateY(-2px)}
.search-recent .sr svg{opacity:.6}
.search-foot{padding:6px 12px 13px}
.search-foot a{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;justify-content:center;gap:8px;padding:11px;border-radius:13px;background:var(--sky);color:var(--royal);font-weight:800;font-size:.84rem;transition:all .2s ease}
.search-foot a:hover{background:var(--grad);color:#fff}
.header-right{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;gap:12px;-ms-flex-negative:0;flex-shrink:0;order:3;margin-left:auto;justify-content:flex-end}
.header-right .hamburger{order:1}
.header-right .search-toggle{order:2}
.header-right .theme-toggle{order:3}
.header-right nav.main-nav{order:4}
nav.main-nav{display:-webkit-box;display:-ms-flexbox;display:flex;gap:2px;-webkit-box-align:center;-ms-flex-align:center;align-items:center;-ms-flex-negative:0;flex-shrink:0;order:2}
nav.main-nav:before{content:"";width:1px;height:24px;background:rgba(255,255,255,.22);margin-right:12px}
nav.main-nav a{position:relative;padding:10px 14px;border-radius:50px;font-weight:700;font-size:.9rem;color:#fff;white-space:nowrap;transition:background .22s ease, transform .22s ease, opacity .22s ease;display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;gap:8px}
nav.main-nav a:hover{background:rgba(255,255,255,.16);color:#fff}
nav.main-nav a svg{display:none}
.theme-toggle{width:50px;height:29px;border-radius:50px;border:1.5px solid rgba(255,255,255,.4);background:rgba(255,255,255,.15);position:relative;-ms-flex-negative:0;flex-shrink:0;display:inline-flex;align-items:center;cursor:pointer;transition:all .3s cubic-bezier(.4,0,.2,1);overflow:hidden;padding:0}
.theme-toggle:hover{-webkit-transform:scale(1.08);transform:scale(1.08);border-color:rgba(255,255,255,.6);background:rgba(255,255,255,.22)}
.theme-toggle:active{-webkit-transform:scale(.95);transform:scale(.95)}
.theme-toggle:before{content:"";position:absolute;top:2px;left:2px;width:21px;height:21px;border-radius:50%;background:linear-gradient(135deg,#fff,#dfe8ff);display:block;box-shadow:0 2px 8px rgba(0,0,0,.25);transition:transform .4s cubic-bezier(.4,0,.2,1), background .4s ease}
.theme-toggle:after{content:"\2600";position:absolute;left:9px;top:50%;transform:translateY(-50%);font-size:11px;line-height:1;color:#f59e0b;transition:opacity .3s ease, transform .3s ease}
[data-theme="dark"] .theme-toggle{background:rgba(255,255,255,.2);border-color:rgba(255,255,255,.45)}
[data-theme="dark"] .theme-toggle:before{-webkit-transform:translateX(21px);transform:translateX(21px);background:linear-gradient(135deg,#28345E,#5F92FF)}
[data-theme="dark"] .theme-toggle:after{content:"\263E";left:auto;right:9px;color:#f8d76a}
.search-toggle{display:none;width:42px;height:42px;border-radius:12px;background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.3);color:#fff;-webkit-box-align:center;-ms-flex-align:center;align-items:center;-webkit-box-pack:center;-ms-flex-pack:center;justify-content:center;cursor:pointer;transition:all .3s cubic-bezier(.4,0,.2,1)}
.search-toggle:hover{background:rgba(255,255,255,.22);-webkit-transform:scale(1.05);transform:scale(1.05)}
.search-toggle:active{-webkit-transform:scale(.95);transform:scale(.95)}
.search-toggle.active{background:rgba(255,255,255,.28);-webkit-box-shadow:0 0 0 3px rgba(255,255,255,.2);box-shadow:0 0 0 3px rgba(255,255,255,.2)}
.search-toggle svg{width:19px;height:19px}
.hamburger{display:none;width:42px;height:42px;border-radius:12px;background:rgba(255,255,255,.14);color:#fff;border:1px solid rgba(255,255,255,.3);align-items:center;justify-content:center;font-size:1.5rem;cursor:pointer;transition:all .3s cubic-bezier(.4,0,.2,1);position:relative;overflow:hidden}
.hamburger:hover{background:rgba(255,255,255,.22);-webkit-transform:scale(1.05);transform:scale(1.05)}
.hamburger:active{-webkit-transform:scale(.95);transform:scale(.95)}
.hamburger.is-open{background:rgba(255,255,255,.28);-webkit-transform:rotate(90deg);transform:rotate(90deg)}
.mobile-search-wrap{display:none;position:relative;background:var(--card);border-bottom:1px solid var(--line);padding:12px 24px;z-index:90}
.mobile-search-wrap.open{display:block}
.mobile-search-inner{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;gap:12px;max-width:1280px;margin:0 auto;position:relative}
.mobile-search-inner input{width:100%;padding:12px 18px 12px 46px;border:1.5px solid var(--line);border-radius:50px;background:var(--bg);color:var(--ink);font:600 .92rem 'Manrope';outline:none;transition:border-color .25s ease, box-shadow .25s ease}
.mobile-search-inner input::-webkit-input-placeholder{color:var(--muted)}
.mobile-search-inner input::placeholder{color:var(--muted)}
.mobile-search-inner input:focus{border-color:var(--royal);box-shadow:0 0 0 4px rgba(37,99,235,.14),0 6px 20px rgba(37,99,235,.1)}
.mobile-search-inner > svg{position:absolute;left:16px;top:50%;-webkit-transform:translateY(-50%);transform:translateY(-50%);width:18px;height:18px;stroke:var(--muted);pointer-events:none;-webkit-transition:stroke .25s ease;transition:stroke .25s ease}
.mobile-search-inner:focus-within > svg{stroke:var(--royal)}
.mobile-search-close{width:40px;height:40px;border-radius:12px;background:var(--sky);border:1px solid var(--line);color:var(--ink);display:grid;place-items:center;font-size:1.4rem;cursor:pointer;transition:all .22s ease}
.mobile-search-close:hover{background:var(--royal);color:#fff;transform:scale(1.05)}
.mobile-search-close svg{width:18px;height:18px}
.mobile-menu-backdrop,.mobile-menu-backdrop.open{display:none !important}
nav.main-nav.open{display:-webkit-box;display:-ms-flexbox;display:flex;background:rgba(255,255,255,.97);border:1px solid rgba(255,255,255,.5);border-radius:16px;box-shadow:0 12px 30px rgba(8,20,64,.16);padding:8px;gap:4px;transition:all .3s cubic-bezier(.4,0,.2,1);flex-direction:column;align-items:stretch;animation:menuSlideDown .3s cubic-bezier(.4,0,.2,1) both}
[data-theme="dark"] nav.main-nav.open{background:rgba(15,23,42,.92);border-color:rgba(255,255,255,.08)}
@keyframes menuSlideDown{from{opacity:0;transform:translateY(-12px) scale(.97)}to{opacity:1;transform:translateY(0) scale(1)}}
nav.main-nav.open a{color:var(--ink);text-align:left;font-weight:700;font-size:.95rem;border-radius:14px;padding:14px 18px;background:transparent;border:none;transition:all .25s cubic-bezier(.4,0,.2,1);display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;gap:12px;position:relative;overflow:hidden}
nav.main-nav.open a:before{content:"";position:absolute;left:0;top:50%;-webkit-transform:translateY(-50%);transform:translateY(-50%);width:3px;height:0;background:var(--royal);border-radius:0 4px 4px 0;transition:height .25s cubic-bezier(.4,0,.2,1)}
nav.main-nav.open a:hover{background:var(--sky);color:var(--royal);border:none;-webkit-transform:none;transform:none}
nav.main-nav.open a:hover:before{height:24px}
nav.main-nav.open a:active{-webkit-transform:scale(.98);transform:scale(.98)}
nav.main-nav.open a:nth-child(1){-webkit-animation:menuItemFade .3s .05s ease both;animation:menuItemFade .3s .05s ease both}
nav.main-nav.open a:nth-child(2){-webkit-animation:menuItemFade .3s .1s ease both;animation:menuItemFade .3s .1s ease both}
nav.main-nav.open a:nth-child(3){-webkit-animation:menuItemFade .3s .15s ease both;animation:menuItemFade .3s .15s ease both}
nav.main-nav.open a:nth-child(4){-webkit-animation:menuItemFade .3s .2s ease both;animation:menuItemFade .3s .2s ease both}
@keyframes menuItemFade{from{opacity:0;transform:translateX(-12px)}to{opacity:1;transform:translateX(0)}}

/* Hero */
.hero{position:relative;isolation:isolate;text-align:center;padding:58px 24px 34px;background:
radial-gradient(circle at 14% 18%,rgba(96,165,250,.18),transparent 26%),
radial-gradient(circle at 86% 20%,rgba(124,77,255,.13),transparent 24%),
linear-gradient(180deg,#F6FAFF 0%,#EEF6FF 54%,#F8FBFF 100%);overflow:hidden;border-bottom:1px solid rgba(37,99,235,.08)}
[data-theme="dark"] .hero{background:radial-gradient(circle at 14% 16%,rgba(37,99,235,.15),transparent 27%),radial-gradient(circle at 88% 22%,rgba(124,77,255,.10),transparent 25%),linear-gradient(180deg,#091426 0%,#07101F 62%,#081325 100%);border-bottom-color:rgba(96,165,250,.10)}
.hero::before,.hero::after{content:"";position:absolute;pointer-events:none;z-index:-1;border-radius:50%;filter:blur(8px)}
.hero::before{width:620px;height:620px;left:-290px;top:-260px;background:radial-gradient(circle,rgba(59,130,246,.18),transparent 70%)}
.hero::after{width:650px;height:650px;right:-300px;top:-250px;background:radial-gradient(circle,rgba(99,102,241,.14),transparent 70%)}
.hero-inner{position:relative;z-index:3;max-width:850px;margin:0 auto}
.pill-badge{display:inline-flex;align-items:center;gap:8px;padding:8px 18px;border-radius:999px;background:rgba(255,255,255,.74);border:1px solid rgba(37,99,235,.12);box-shadow:0 10px 28px rgba(37,99,235,.10),inset 0 1px 0 rgba(255,255,255,.92);color:#1543B7;font:800 .82rem 'Manrope';backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);animation:fadeUp .65s ease both}
[data-theme="dark"] .pill-badge{background:rgba(14,28,55,.78);border-color:rgba(96,165,250,.18);color:#93C5FD;box-shadow:0 10px 28px rgba(0,0,0,.28)}
.hero-badge-spark{font-size:1rem;color:#4F46E5;line-height:1}
.hero h1{font-size:clamp(2.05rem,5.2vw,4.05rem);font-weight:800;line-height:1.03;letter-spacing:-.055em;margin:26px auto 14px;max-width:830px;color:#0C1D62;position:relative;z-index:2;animation:fadeUp .65s .08s ease both}
[data-theme="dark"] .hero h1{color:#F8FAFF}
.hero h1 em{font-style:normal;display:block;margin-top:5px;background:linear-gradient(90deg,#1D5EFF,#387FF4 55%,#1E55D9);-webkit-background-clip:text;background-clip:text;color:transparent}
.hero-lead{max-width:700px!important;margin:0 auto!important;color:#50658E!important;font-size:clamp(.94rem,1.55vw,1.12rem)!important;line-height:1.65!important;position:relative;z-index:2;animation:fadeUp .65s .16s ease both}
[data-theme="dark"] .hero-lead{color:#9CB0D5!important}
.hero-search{display:flex;align-items:stretch;width:min(810px,92vw);height:58px;margin:30px auto 0;border-radius:999px;background:#fff;border:1px solid rgba(37,99,235,.12);box-shadow:0 14px 38px rgba(37,99,235,.13);overflow:hidden;position:relative;z-index:4;animation:fadeUp .65s .22s ease both}
[data-theme="dark"] .hero-search{background:#0E1B34;border-color:rgba(96,165,250,.18);box-shadow:0 14px 36px rgba(0,0,0,.35)}
.hero-search-icon{display:grid;place-items:center;width:62px;flex:0 0 62px;color:#3B5C92}
[data-theme="dark"] .hero-search-icon{color:#8EABD8}
.hero-search-icon svg{width:25px;height:25px}
.hero-search input{min-width:0;flex:1;border:0;outline:0;background:transparent;color:#243B68;font:600 1rem 'Manrope';padding:0 12px}
[data-theme="dark"] .hero-search input{color:#EFF6FF}
.hero-search input::placeholder{color:#6E84AA}
.hero-search button{flex:0 0 175px;background:linear-gradient(135deg,#2381F6,#2854F4);color:#fff;font:800 .95rem 'Sora';display:flex;align-items:center;justify-content:center;gap:10px;transition:filter .2s ease,transform .2s ease}
.hero-search button:hover{filter:brightness(1.06)}
.hero-search button:active{transform:scale(.985)}
.hero-search button svg{width:18px;height:18px}
.hero-chips{display:flex;flex-wrap:wrap;justify-content:center;gap:10px;margin:17px auto 0;position:relative;z-index:3;animation:fadeUp .65s .28s ease both}
.hero-chip{--hc:#2563EB;display:inline-flex;align-items:center;gap:7px;padding:7px 15px;border-radius:999px;background:rgba(255,255,255,.72);border:1px solid color-mix(in srgb,var(--hc) 16%,transparent);box-shadow:0 7px 18px rgba(38,68,135,.06);color:#243B68;font:800 .78rem 'Manrope';transition:transform .2s ease,box-shadow .2s ease,border-color .2s ease}
[data-theme="dark"] .hero-chip{background:rgba(14,27,51,.75);color:#E9F0FF}
.hero-chip:hover{transform:translateY(-2px);box-shadow:0 10px 22px rgba(38,68,135,.10);border-color:color-mix(in srgb,var(--hc) 30%,transparent)}
.hero-chip svg{width:17px;height:17px;color:var(--hc)}
.hero-chip.seo{--hc:#10B981}.hero-chip.text{--hc:#F59E0B}.hero-chip.image{--hc:#0EA5E9}.hero-chip.dev{--hc:#7C3AED}.hero-chip.calc{--hc:#F43F5E}
.hero-trust{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));max-width:730px;margin:34px auto 0;position:relative;z-index:3;animation:fadeUp .65s .34s ease both}
.hero-trust-item{display:flex;align-items:center;gap:13px;text-align:left;padding:0 26px;min-width:0}
.hero-trust-item+ .hero-trust-item{border-left:1px solid rgba(37,99,235,.14)}
[data-theme="dark"] .hero-trust-item+ .hero-trust-item{border-left-color:rgba(96,165,250,.14)}
.hero-trust-icon{width:36px;height:36px;flex:0 0 36px;display:grid;place-items:center;color:#1E6CF0}
.hero-trust-icon svg{width:27px;height:27px;stroke:currentColor}
.hero-trust-copy strong{display:block;color:#10245C;font:800 .86rem 'Sora';line-height:1.25}
[data-theme="dark"] .hero-trust-copy strong{color:#F4F7FF}
.hero-trust-copy small{display:block;margin-top:3px;color:#60749B;font:500 .72rem 'Manrope';line-height:1.35}
[data-theme="dark"] .hero-trust-copy small{color:#8FA5CD}
.hero-feature-strip{display:grid;grid-template-columns:repeat(4,1fr);align-items:center;max-width:780px;margin:34px auto 0;padding:10px 22px;border-radius:999px;background:rgba(255,255,255,.48);border:1px solid rgba(255,255,255,.82);box-shadow:inset 0 1px 0 rgba(255,255,255,.84),0 9px 28px rgba(37,99,235,.05);position:relative;z-index:3;backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);animation:fadeUp .65s .4s ease both}
[data-theme="dark"] .hero-feature-strip{background:rgba(14,27,51,.55);border-color:rgba(96,165,250,.12)}
.hero-feature{display:flex;align-items:center;justify-content:center;gap:8px;color:#304A78;font:700 .73rem 'Manrope';white-space:nowrap}
[data-theme="dark"] .hero-feature{color:#A8BADE}
.hero-feature+ .hero-feature{border-left:1px solid rgba(37,99,235,.11)}
[data-theme="dark"] .hero-feature+ .hero-feature{border-left-color:rgba(96,165,250,.12)}
.hero-feature svg{width:18px;height:18px;color:#2582F5;stroke:currentColor}
.hero-icon-rail{position:absolute;top:0;bottom:0;width:118px;z-index:2;pointer-events:none;overflow:hidden;opacity:.98}
.hero-icon-rail.left{left:max(18px,calc(50% - 760px))}.hero-icon-rail.right{right:max(18px,calc(50% - 760px))}
.hero-icon-rail::before{content:"";position:absolute;top:28px;bottom:34px;left:50%;width:2px;transform:translateX(-50%);background:linear-gradient(180deg,transparent,#3687FF 14%,#2F6BFF 72%,transparent);opacity:.42;border-radius:99px;box-shadow:0 0 14px rgba(47,107,255,.34)}
.hero-icon-stack{display:flex;flex-direction:column;align-items:center;gap:20px;padding:10px 0;position:relative;z-index:2}
.hero-icon-rail.left .hero-icon-stack{animation:heroIconsUp 18s linear infinite}.hero-icon-rail.right .hero-icon-stack{animation:heroIconsUp 20s linear infinite}
.hero-flow-icon{--hero-accent:#2563EB;width:72px;height:72px;min-height:72px;border-radius:22px;display:grid;place-items:center;background:linear-gradient(145deg,rgba(255,255,255,.94),rgba(235,244,255,.84));border:1px solid rgba(255,255,255,.92);box-shadow:0 15px 26px rgba(35,87,178,.14),inset 0 1px 0 #fff,inset 0 -7px 18px rgba(37,99,235,.045);transform:rotate(-3deg);position:relative}
.hero-icon-rail.right .hero-flow-icon{transform:rotate(3deg)}
[data-theme="dark"] .hero-flow-icon{background:linear-gradient(145deg,rgba(27,44,77,.94),rgba(11,23,46,.92));border-color:rgba(129,169,255,.14);box-shadow:0 15px 28px rgba(0,0,0,.32),inset 0 1px 0 rgba(255,255,255,.06)}
.hero-flow-icon::after{content:"";position:absolute;width:7px;height:7px;border-radius:50%;background:#2582F5;left:50%;bottom:-15px;transform:translateX(-50%);box-shadow:0 0 0 3px rgba(37,130,245,.12),0 0 11px rgba(37,130,245,.55)}
.hero-flow-icon svg{width:48px;height:48px;display:block;filter:drop-shadow(0 6px 8px rgba(37,99,235,.10))}
.hero-flow-icon:nth-child(2n){transform:translateX(8px) rotate(3deg)}.hero-icon-rail.right .hero-flow-icon:nth-child(2n){transform:translateX(-8px) rotate(-3deg)}
.hero-bg-orb{position:absolute;width:44px;height:44px;border-radius:15px;background:rgba(70,126,245,.16);filter:blur(7px);opacity:.46;pointer-events:none;z-index:1}.hero-bg-orb.o1{left:15%;top:11%}.hero-bg-orb.o2{left:19%;top:42%;background:rgba(244,63,94,.14)}.hero-bg-orb.o3{right:16%;top:14%;background:rgba(124,77,255,.13)}.hero-bg-orb.o4{right:19%;top:44%;background:rgba(245,158,11,.13)}
@keyframes heroIconsUp{from{transform:translateY(0)}to{transform:translateY(calc(-50% - 10px))}}
@keyframes fadeUp{from{opacity:0;transform:translateY(20px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.hero-icon-stack,.pill-badge,.hero h1,.hero-lead,.hero-search,.hero-chips,.hero-trust,.hero-feature-strip{animation:none!important}}
@media (max-width:1180px){.hero-icon-rail{width:82px;opacity:.62}.hero-flow-icon{width:58px;height:58px;min-height:58px;border-radius:18px}.hero-flow-icon svg{width:39px;height:39px}.hero-icon-rail.left{left:8px}.hero-icon-rail.right{right:8px}.hero-inner{max-width:760px}}
@media (max-width:900px){.hero{padding:50px 18px 30px}.hero-icon-rail{display:none}.hero h1{max-width:720px}.hero-trust{max-width:700px}.hero-feature-strip{max-width:720px}}
@media (max-width:680px){.hero{padding:38px 14px 24px}.pill-badge{font-size:.73rem;padding:7px 13px}.hero h1{font-size:clamp(2rem,10.5vw,3rem);margin-top:20px}.hero-lead{font-size:.91rem!important;line-height:1.55!important;padding:0 4px}.hero-search{height:52px;margin-top:23px;width:100%}.hero-search-icon{width:48px;flex-basis:48px}.hero-search-icon svg{width:21px;height:21px}.hero-search input{font-size:.9rem;padding:0 4px}.hero-search button{flex-basis:104px;font-size:.82rem}.hero-search button span{display:none}.hero-chips{gap:7px;margin-top:14px}.hero-chip{padding:6px 10px;font-size:.7rem}.hero-trust{grid-template-columns:1fr;gap:0;margin-top:25px;max-width:370px}.hero-trust-item{padding:11px 14px}.hero-trust-item+ .hero-trust-item{border-left:0;border-top:1px solid rgba(37,99,235,.11)}.hero-feature-strip{display:flex;overflow-x:auto;justify-content:flex-start;gap:0;border-radius:18px;padding:10px 8px;margin-top:22px;scrollbar-width:none}.hero-feature-strip::-webkit-scrollbar{display:none}.hero-feature{flex:0 0 auto;padding:0 13px;font-size:.68rem}.hero-feature:first-child{padding-left:6px}.hero-feature+ .hero-feature{border-left:1px solid rgba(37,99,235,.10)}}
.btn{padding:13px 30px;border-radius:50px;font-weight:800;font-size:.92rem;font-family:'Sora';display:-webkit-inline-box;display:-ms-inline-flexbox;display:inline-flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;gap:9px;-webkit-transition:-webkit-transform .25s;transition:transform .25s}
.btn svg{display:block}
.btn-primary{background:var(--grad);color:#fff;-webkit-box-shadow:var(--shadow-lg);box-shadow:var(--shadow-lg)}
.btn-primary:hover,.btn-ghost:hover{-webkit-transform:translateY(-3px);transform:translateY(-3px)}
.btn-ghost{background:var(--card);color:var(--ink);border:1.5px solid var(--line);-webkit-box-shadow:var(--shadow);box-shadow:var(--shadow)}

/* Stats */
.stats{max-width:1000px;margin:28px auto 4px;padding:0 24px;display:grid;grid-template-columns:repeat(4,1fr);gap:20px}
.stat{padding:21px 14px;text-align:center;color:#fff;position:relative;overflow:hidden;border:1px solid rgba(255,255,255,.14);border-radius:16px;-webkit-box-shadow:0 10px 24px rgba(30,64,175,.14);box-shadow:0 10px 24px rgba(30,64,175,.14);-webkit-transition:transform .25s ease,box-shadow .25s ease;transition:transform .25s ease,box-shadow .25s ease}
.stat:after{content:"";position:absolute;width:90px;height:90px;border-radius:50%;right:-42px;top:-54px;background:rgba(255,255,255,.15);pointer-events:none}
.stat:hover{-webkit-transform:translateY(-3px);transform:translateY(-3px);-webkit-box-shadow:0 14px 30px rgba(30,64,175,.2);box-shadow:0 14px 30px rgba(30,64,175,.2)}
.stat-num{font-size:2.25rem;font-weight:800;line-height:1.05;position:relative;z-index:1;color:#fff;letter-spacing:-.045em}
.stat-lbl{font-size:.68rem;font-weight:800;letter-spacing:.105em;text-transform:uppercase;color:#fff;opacity:.9;position:relative;z-index:1;margin-top:7px}
.stat:nth-child(1){background:linear-gradient(135deg,#1E40AF,#2563EB)}
.stat:nth-child(2){background:linear-gradient(135deg,#2563EB,#3B82F6)}
.stat:nth-child(3){background:linear-gradient(135deg,#183153,#4C91DA)}
.stat:nth-child(4){background:linear-gradient(135deg,#1E3A8A,#2F6BDE)}


/* Hero Slider */
.hero-slider{max-width:1180px;margin:0 auto;padding:12px 24px 0}
.hs-wrap{position:relative;overflow:hidden;isolation:isolate;border-radius:22px;background:linear-gradient(135deg,var(--card) 0%,var(--sky) 58%,color-mix(in srgb,var(--royal) 10%,var(--card)) 100%);border:1px solid color-mix(in srgb,var(--royal) 24%,var(--line));-webkit-box-shadow:0 18px 48px rgba(37,99,235,.14);box-shadow:0 18px 48px rgba(37,99,235,.14);touch-action:pan-y}
.hs-wrap:before,.hs-wrap:after{content:"";position:absolute;border-radius:50%;pointer-events:none;z-index:-1}
.hs-wrap:before{width:280px;height:280px;right:-95px;top:-155px;background:radial-gradient(circle,rgba(59,130,246,.22),transparent 70%)}
.hs-wrap:after{width:220px;height:220px;left:38%;bottom:-180px;background:radial-gradient(circle,rgba(96,165,250,.18),transparent 70%)}
.hs-track{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-transition:-webkit-transform .55s cubic-bezier(.4,0,.2,1);transition:transform .55s cubic-bezier(.4,0,.2,1)}
.hs-slide{min-width:100%;min-height:224px;display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;gap:32px;padding:28px 38px;position:relative}
.hs-copy{position:relative;z-index:2;min-width:0;-webkit-box-flex:1;-ms-flex:1;flex:1}
.hs-kicker{display:-webkit-inline-box;display:-ms-inline-flexbox;display:inline-flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;gap:7px;margin-bottom:9px;padding:5px 10px;border-radius:50px;background:var(--card);border:1px solid var(--line);color:var(--royal);font:800 .66rem 'Manrope';letter-spacing:.08em;text-transform:uppercase;box-shadow:0 6px 18px rgba(37,99,235,.08)}
.hs-kicker:before{content:"";width:6px;height:6px;border-radius:50%;background:var(--royal);box-shadow:0 0 0 4px rgba(37,99,235,.12)}
.hs-slide h3{font-size:clamp(1.28rem,2.4vw,1.8rem);font-weight:800;line-height:1.18;margin-bottom:8px;letter-spacing:-.025em}
.hs-slide h3 span{color:var(--royal)}
.hs-slide p{color:var(--muted);font-size:.9rem;max-width:590px;margin-bottom:12px}
.hs-preview{display:-webkit-box;display:-ms-flexbox;display:flex;gap:7px;-ms-flex-wrap:wrap;flex-wrap:wrap;margin:0 0 15px}
.hs-preview a{display:inline-flex;align-items:center;padding:6px 10px;border-radius:9px;background:color-mix(in srgb,var(--card) 82%,transparent);border:1px solid var(--line);color:var(--ink);font-size:.72rem;font-weight:700;transition:all .2s ease}
.hs-preview a:hover{border-color:var(--royal);color:var(--royal);transform:translateY(-2px)}
.hs-art{-ms-flex-negative:0;flex-shrink:0;margin-left:auto;width:170px;height:146px;border-radius:24px;display:grid;place-items:center;position:relative;background:linear-gradient(145deg,rgba(255,255,255,.92),rgba(219,234,254,.72));border:1px solid rgba(255,255,255,.8);box-shadow:inset 0 1px 0 rgba(255,255,255,.9),0 18px 38px rgba(37,99,235,.2);transform:rotate(2deg)}
[data-theme="dark"] .hs-art{background:linear-gradient(145deg,rgba(24,43,82,.95),rgba(13,24,48,.85));border-color:rgba(96,165,250,.18)}
.hs-art:before{content:"";position:absolute;inset:12px;border:1px dashed rgba(37,99,235,.2);border-radius:17px}
.hs-art svg{width:94px;height:94px;position:relative;z-index:1;filter:drop-shadow(0 9px 14px rgba(37,99,235,.14))}
.hs-art img{width:100%;height:100%;object-fit:contain;position:relative;z-index:1;filter:drop-shadow(0 9px 14px rgba(37,99,235,.14))}
.hs-count{position:absolute;right:-7px;bottom:13px;z-index:2;padding:6px 9px;border-radius:10px;background:var(--grad);color:#fff;font:800 .68rem 'Manrope';box-shadow:0 8px 18px rgba(37,99,235,.28);transform:rotate(-2deg)}
.hs-nav{position:absolute;bottom:10px;z-index:4;width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:var(--card);border:1px solid var(--line);color:var(--royal);box-shadow:0 7px 20px rgba(37,99,235,.14);font-size:1rem;font-weight:800;transition:all .2s ease}
.hs-nav:hover{background:var(--royal);color:#fff;border-color:var(--royal)}
.hs-nav.prev{left:14px}.hs-nav.next{right:14px}
.hs-dots{display:-webkit-box;display:-ms-flexbox;display:flex;gap:6px;-webkit-box-pack:center;-ms-flex-pack:center;justify-content:center;padding:12px 8px 5px;overflow-x:auto;scrollbar-width:none}
.hs-dots::-webkit-scrollbar{display:none}
.hs-dot{flex:0 0 auto;width:7px;height:7px;border-radius:50%;background:var(--line);cursor:pointer;border:none;padding:0;-webkit-transition:all .3s;transition:all .3s}
.hs-dot.active{background:var(--royal);width:20px;border-radius:50px}
@media (max-width:700px){.hs-slide{min-height:360px;padding:22px 18px 28px;-webkit-box-orient:vertical;-webkit-box-direction:normal;-ms-flex-direction:column;flex-direction:column;gap:16px;text-align:center}.hs-copy{width:100%;margin-inline:auto}.hs-kicker{margin-bottom:8px}.hs-slide h3{max-width:270px;margin-left:auto;margin-right:auto}.hs-slide p{font-size:.82rem;margin:0 auto 11px}.hs-preview{justify-content:center;margin-bottom:13px}.hs-preview a:nth-child(n+3){display:none}.hs-slide .btn{padding:10px 18px;font-size:.78rem}.hs-art{order:-1;width:112px;height:96px;margin:0 auto;border-radius:18px}.hs-art:before{inset:8px;border-radius:13px}.hs-art svg{width:62px;height:62px}.hs-art img{width:100%;height:100%}.hs-count{right:auto;left:50%;bottom:-8px;-webkit-transform:translateX(-50%);transform:translateX(-50%);white-space:nowrap}.hs-nav{bottom:8px;width:32px;height:32px}.hs-dots{padding-inline:50px}}

/* Section titles */
#all-tools,.tool-section{scroll-margin-top:110px}
.section-head{text-align:center;padding:22px 12px 11px}
.section-head h2{font-size:clamp(1.6rem,3.4vw,2.3rem);font-weight:800}
.section-head p{color:var(--muted);margin-top:10px;font-size:.98rem}

/* Category pills */
.category-browser{max-width:1180px;margin:32px auto 0;padding:28px 22px 18px;background:var(--card);border:1px solid var(--line);border-radius:22px;-webkit-box-shadow:0 16px 42px rgba(37,99,235,.09);box-shadow:0 16px 42px rgba(37,99,235,.09);position:relative;overflow:hidden}
.category-browser:before{content:"";position:absolute;width:210px;height:210px;right:-110px;top:-140px;border-radius:50%;background:radial-gradient(circle,rgba(59,130,246,.13),transparent 70%);pointer-events:none}
.category-browser .section-head{padding:0 56px 20px;position:relative;z-index:1}
.category-browser .section-head h2{font-size:clamp(1.45rem,2.7vw,2rem);letter-spacing:-.03em}
.category-browser .section-head p{margin-top:7px;font-size:.9rem}
