  .cat-ico svg{width:23px;height:23px}
  .cat-pill .nm{font-size:.72rem}
  .tool-grid{grid-template-columns:repeat(2,minmax(0,1fr));padding:10px;gap:4px 6px}
  .foot-grid{grid-template-columns:1fr;gap:30px;padding:44px 24px 20px}
  .hero{padding:32px 16px 30px}
  .hero h1{font-size:clamp(1.55rem,6.2vw,1.95rem);letter-spacing:-.035em;margin-top:16px}
  .hero p{font-size:.94rem;line-height:1.6}
  .btn{padding:12px 24px;font-size:.88rem}
  .hero-slider{padding:8px 14px 0}
  .stats{margin:22px 14px 4px;padding:0;gap:9px}
  .stat{padding:14px 9px}
  .stat-num{font-size:1.55rem}
  .section-head{padding:30px 16px 14px}
  .section-head h2{font-size:1.55rem;letter-spacing:-.025em}
  .section-head p{font-size:.88rem;margin-top:7px}
  .tools-wrap,.blog-posts{padding-left:14px;padding-right:14px}
  .tools-wrap{padding-bottom:38px}
  .tool-section{margin-top:12px;border-radius:14px}
  .sec-bar{padding:12px 14px;font-size:.88rem;cursor:pointer}
  .sec-meta{font-size:.64rem}.sec-chevron{display:inline-block}
  .tool-section.mobile-collapsed .tool-grid{display:none}
  .tool-section.mobile-collapsed .sec-chevron{-webkit-transform:rotate(-90deg);transform:rotate(-90deg)}
  .tool-link{gap:8px;padding:9px 8px;font-size:.76rem;line-height:1.28;border-radius:10px}
  .tool-ico{width:30px;height:30px;border-radius:8px}
  .tool-ico svg{width:23px;height:23px}
}
@media (max-width:1050px){
  .hero-icon-rail{display:none}
}
@media (max-width:480px){
  .cat-ico{width:50px;height:50px}
  .header-inner{padding:10px 12px;gap:8px}
  .tpw-logo-slot{max-width:calc(100% - 126px)}
  .tpw-logo-slot img.logo-image{--tpw-logo-width:150px}
  footer.tpw-footer img.footer-logo-image{--tpw-footer-logo-width:150px}
  .tpw-logo-slot .logo{width:auto;max-width:100%;flex:0 0 auto}
  .logo-text{font-size:.88rem;white-space:nowrap}
