  .logo-badge{width:36px;height:36px;border-radius:10px}
  .logo-badge svg{width:18px;height:18px}
  .header-right{gap:5px}
  .header-right .hamburger{width:36px;height:36px;font-size:1.3rem}
  .header-right .search-toggle{width:36px;height:36px}
  .theme-toggle{width:44px;height:26px}
  .theme-toggle:before{width:18px;height:18px}
  [data-theme="dark"] .theme-toggle:before{-webkit-transform:translateX(18px);transform:translateX(18px)}
  .header-search input{font-size:.86rem}
  .mobile-search-inner input{font-size:.86rem}
  .mobile-search-inner{padding:0 4px}
  .category-browser{margin:22px 10px 0;padding:21px 10px 14px;border-radius:17px}
  .category-browser .section-head{padding:0 8px 16px}
  .category-browser .section-head h2{font-size:1.35rem}
  .category-browser .section-head p{font-size:.82rem;line-height:1.5}
.cats{padding-inline:0;gap:8px}
.cat-pill{flex-basis:84px;min-height:74px;padding:8px 7px 7px}
  .cat-ico{width:40px;height:40px;border-radius:11px}
  .cat-ico svg{width:21px;height:21px}
  .cat-pill .nm{font-size:.7rem}
  .cats-nav{margin-top:8px;gap:9px}
  .cats-nav button{width:34px;height:34px}
  .tool-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .stat-num{font-size:1.45rem}
  .tool-section{border-radius:13px}
  .sec-bar{padding:11px 12px}
  .pill-badge{padding:7px 12px;font-size:.72rem;line-height:1.35}
  .hero h1{max-width:340px;line-height:1.16}
  .hero h1 em{margin-top:5px}
  .hero p{max-width:350px;font-size:.92rem;line-height:1.65}
  .hero-trust{gap:8px;margin-top:18px}
  .hero-trust span{padding:6px 10px;font-size:.7rem}
  .hero-trust span:nth-child(3){display:none}
  .hero-slider{padding-inline:18px}
  .hero-slider .hs-wrap{width:100%;max-width:calc(100vw - 36px);margin-inline:auto;box-sizing:border-box}
  .hs-slide{min-height:348px;padding:18px 14px 24px;gap:24px}
  .hs-slide h3{font-size:1.2rem;margin-bottom:6px}
  .hs-art{width:96px;height:82px}.hs-art svg{width:54px;height:54px}.hs-art img{width:100%;height:100%}
  .hs-preview a{font-size:.66rem;padding:5px 7px}
  .stats{margin:18px 10px 4px;padding:0;gap:7px}
  .stat{padding:12px 6px}.stat-lbl{font-size:.58rem;letter-spacing:.07em}
  .tools-wrap{padding-left:10px;padding-right:10px}
  .tool-card-btn,.action-btn,.copy-btn,.clear-btn,.download-btn,.generate-btn,.add-item-btn,.copy-all-btn,.remove-btn,.alt-btn,.qr-btn,.pw-btn,.case-btn,.upload-zone,.btn{min-height:44px;justify-content:center}
  .btn-row>*,.preview-actions>*,.tool-card-actions>*,.tool-actions-bar>*,.uuid-actions>*,.pw-actions-row>*,.qr-btn-row>*,.wc-actions>*{flex:1 1 auto}
}
@media (max-width:360px){
  .tpw-logo-slot{max-width:calc(100% - 112px)}
  .tpw-logo-slot img.logo-image{--tpw-logo-width:140px}
  footer.tpw-footer img.footer-logo-image{--tpw-footer-logo-width:140px}
  .tpw-logo-slot .logo{width:auto;max-width:100%;flex:0 0 auto}
  .logo-text{font-size:.82rem}
  .logo-badge{width:32px;height:32px}
  .logo-badge svg{width:16px;height:16px}
  .header-right .hamburger{width:34px;height:34px;font-size:1.2rem}
  .header-right .search-toggle{width:34px;height:34px}
  .theme-toggle{width:40px;height:24px}
  .theme-toggle:before{width:16px;height:16px}
  [data-theme="dark"] .theme-toggle:before{-webkit-transform:translateX(16px);transform:translateX(16px)}
  .tool-grid{grid-template-columns:repeat(2,minmax(0,1fr));padding:8px;gap:3px}
  .tool-link{padding:8px 6px;font-size:.7rem;gap:6px}
  .tool-ico{width:27px;height:27px}.tool-ico svg{width:21px;height:21px}
  .hero h1{font-size:1.45rem}
  .hero p{font-size:.9rem}
  .category-browser{margin-inline:8px;padding-inline:8px}
  .cat-pill{flex-basis:80px}
}
@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *,*:before,*:after{animation-duration:.01ms !important;animation-iteration-count:1 !important;scroll-behavior:auto !important;transition-duration:.01ms !important}
}
@media (forced-colors:active){
  .btn-primary,.primary,.cat-pill.active,.sec-bar{border:1px solid ButtonText}
}

body.script:
//
function scrollToThemeTarget(id,updateHash){
  var section = document.getElementById(id);
  if (!section) return false;
  var heading = id === 'all-tools' ? (section.querySelector('h2') || section) : (section.querySelector('.sec-bar') || section.querySelector('h2,h3') || section);
  var header = document.querySelector('.tpw-header');
  var offset = (header ? header.offsetHeight : 70) + 8;
  var top = heading.getBoundingClientRect().top + window.pageYOffset - offset;
  window.scrollTo({top:Math.max(0, top),behavior:'smooth'});
  if (updateHash && window.history && history.replaceState) history.replaceState(null,'','#'+id);
  return true;
}
function selectCategory(target, el){
  var pills = document.querySelectorAll('.cat-pill');
  pills.forEach(function(p){ p.classList.remove('active'); p.setAttribute('aria-pressed', 'false'); });
  el.classList.add('active');
  el.setAttribute('aria-pressed', 'true');
  el.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'});
  document.querySelectorAll('.tool-section').forEach(function(sec){
    sec.classList.toggle('hidden-sec', target !== 'all' && sec.id !== 'sec-' + target);
    if (target !== 'all' && sec.id === 'sec-' + target) {
      sec.classList.remove('mobile-collapsed');
      var bar = sec.querySelector('.sec-bar'); if (bar) bar.setAttribute('aria-expanded', 'true');
    }
  });
  var s = document.getElementById('toolSearch'); if (s) s.value = '';
  var ms = document.getElementById('mobileToolSearch'); if (ms) ms.value = '';
  var n = document.getElementById('noResults'); if (n) n.style.display = 'none';
  scrollToThemeTarget(target === 'all' ? 'all-tools' : 'sec-' + target,false);
}
function shiftCats(dir){
  var g = document.getElementById('catGrid');
  if (g) {
    var card = g.querySelector('.cat-pill');
    if (card) {
      var gap = 12;
      var w = card.offsetWidth + gap;
      g.scrollBy({left: dir * w, behavior:'smooth'});
    }
  }
}
function toggleToolSection(button){
  if (window.innerWidth > 768) return;
  var section = button.closest('.tool-section');
  if (!section) return;
  var collapsed = section.classList.toggle('mobile-collapsed');
  button.setAttribute('aria-expanded', collapsed ? 'false' : 'true');
}
function updateCatNav(){
  var g = document.getElementById('catGrid');
  var prev = document.getElementById('catsPrev');
  var next = document.getElementById('catsNext');
  if (!g || !prev || !next) return;
  var max = Math.max(0, g.scrollWidth - g.clientWidth);
  prev.disabled = g.scrollLeft <= 2;
  next.disabled = g.scrollLeft >= max - 2;
  prev.setAttribute('aria-disabled', String(prev.disabled));
  next.setAttribute('aria-disabled', String(next.disabled));
}
function filterTools(q){
  q = (q || '').trim();
  var ql = tpwNorm(q), qTokens = ql ? ql.split(/\s+/) : [];
  var anyVisible = false;
  document.querySelectorAll('.tool-section').forEach(function(sec){
    var visible = 0;
    sec.querySelectorAll('.tool-link').forEach(function(l){
      var name = (l.getAttribute('data-name') || '').toLowerCase();
      var text = (l.textContent || '');
      var hit = false;
      if (!ql) hit = true;
      else {
        var nNorm = tpwNorm(name);
        var sc = tpwScore({_n:nNorm, _c:tpwNorm(text), _t:tpwTokens(name + ' ' + text)}, ql, qTokens);
        hit = sc > 0 || name.indexOf(q.toLowerCase()) > -1;
      }
      l.style.display = hit ? 'flex' : 'none';
      if (hit) visible++;
    });
    sec.classList.toggle('hidden-sec', visible === 0);
    if (visible > 0) anyVisible = true;
  });
  var n = document.getElementById('noResults');
  if (n) n.style.display = anyVisible ? 'none' : 'block';
  if (ql) document.querySelectorAll('.cat-pill').forEach(function(p){ p.classList.remove('active'); });
}
var TPW_IDX = (window.TPW_FLAT_TOOLS || []).map(function(t){
  return {name:t.name, href:t.href, icon:t.icon, cat:t.cat, _n:tpwNorm(t.name), _c:tpwNorm(t.cat), _t:tpwTokens(t.name)};
});
var TPW_CATS = (typeof SECTIONS !== 'undefined' ? SECTIONS : []).map(function(s){ return {id:s.id, name:s.name}; });
var TPW_POPULAR = ["Word Counter","Password Generator","QR Code Generator","Image to PDF","Unit Converter","Age Calculator","Case Converter","JSON Formatter","Base64 Encode","Length Converter"];
function tpwNorm(s){ return (s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim(); }
function tpwTokens(s){ return tpwNorm(s).split(/\s+/).filter(Boolean); }
function tpwEscapeHtml(s){ return (s || '').replace(/[&<>"']/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); }
function tpwEscapeReg(s){ return (s || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
function tpwLev(a, b){
  var m = a.length, n = b.length;
  if (Math.abs(m - n) > 3) return 99;
  var dp = []; var i, j;
  for (i = 0; i <= m; i++){ dp[i] = [i]; }
  for (j = 0; j <= n; j++){ dp[0][j] = j; }
  for (i = 1; i <= m; i++){
    for (j = 1; j <= n; j++){
      var cost = a.charAt(i - 1) === b.charAt(j - 1) ? 0 : 1;
      dp[i][j] = Math.min(dp[i - 1][j] + 1, dp[i][j - 1] + 1, dp[i - 1][j - 1] + cost);
    }
  }
  return dp[m][n];
}
function tpwScore(it, ql, qTokens){
  var score = 0;
  if (it._n === ql) score = 100;
  else if (it._n.indexOf(ql) === 0) score = 85;
  else if (it._n.indexOf(' ' + ql) > -1 || it._n.indexOf(ql) > -1) score = 65;
  else {
    for (var i = 0; i < qTokens.length; i++){
      var q = qTokens[i];
      for (var j = 0; j < it._t.length; j++){
        var tt = it._t[j];
        if (tt === q) score = Math.max(score, 55);
        else if (tt.indexOf(q) === 0) score = Math.max(score, 50);
        else if (q.length >= 3 && tpwLev(tt, q) <= 1) score = Math.max(score, 45);
      }
    }
  }
  if (score < 48 && it._c.indexOf(ql) > -1) score = Math.max(score, 48);
  if (score === 0 && ql.length >= 4 && tpwLev(it._n, ql) <= 2) score = 40;
  return score;
}
function tpwBadgeHtml(icon){
  if (icon && icon.indexOf('http') === 0) return '<span class="tool-ico"><img loading="lazy" alt="" src="' + icon + '"/></span>';
  if (icon) return '<span class="tool-ico"><svg aria-hidden="true"><use href="#' + icon + '"/></svg></span>';
  return '<span class="tool-ico" style="font-weight:800;font-family:Sora;color:var(--royal)">#</span>';
}
function tpwHighlight(text, q){
  if (!q) return tpwEscapeHtml(text);
  var re = new RegExp('(' + tpwEscapeReg(q) + ')', 'gi');
  return tpwEscapeHtml(text).replace(re, '<mark>$1</mark>');
}
function tpwGetRecent(){ try { return JSON.parse(localStorage.getItem('tpw-recent') || '[]'); } catch(e){ return []; } }
function tpwAddRecent(name, href){
  try {
    var arr = tpwGetRecent().filter(function(r){ return r.href !== href; });
    arr.unshift({name:name, href:href});
    arr = arr.slice(0, 6);
    localStorage.setItem('tpw-recent', JSON.stringify(arr));
  } catch(e){}
}
function tpwRenderSearchItem(it, q, dd){
  var item = document.createElement('a');
  item.className = 'search-item';
  item.setAttribute('role', 'option');
  item.href = it.href;
  item.setAttribute('data-href', it.href);
  item.setAttribute('data-name', it.name);
  item.innerHTML = tpwBadgeHtml(it.icon);
  var info = document.createElement('div');
  info.className = 'search-item-info';
  var nm = document.createElement('div'); nm.className = 'search-item-name'; nm.innerHTML = tpwHighlight(it.name, q);
  var ct = document.createElement('div'); ct.className = 'search-item-cat'; ct.textContent = it.cat;
  info.appendChild(nm); info.appendChild(ct);
  item.appendChild(info);
  dd._tpwItems.push(it);
  return item;
}
function renderSearchDropdown(dd, inputEl, qOrNull, forceShow){
  if (!dd) return;
  var q = qOrNull !== undefined ? qOrNull : (inputEl ? inputEl.value : '');
  q = (q || '').trim();
  if (!q && !forceShow) { while (dd.firstChild) dd.removeChild(dd.firstChild); dd.classList.remove('show'); return; }
  while (dd.firstChild) dd.removeChild(dd.firstChild);
  dd._tpwItems = [];
  dd._tpwInput = inputEl;
  var ql = tpwNorm(q), qTokens = ql ? ql.split(/\s+/) : [];

  var resultsWrap = document.createElement('div');
  resultsWrap.className = 'search-results';
  var contextIt = null;

  if (!q) {
    var shown = 0;
    TPW_POPULAR.forEach(function(pname){
      var it = null;
      for (var k = 0; k < TPW_IDX.length; k++){ if (TPW_IDX[k].name === pname) { it = TPW_IDX[k]; break; } }
      if (it && shown < 8) { resultsWrap.appendChild(tpwRenderSearchItem(it, '', dd)); shown++; }
    });
    if (!shown) {
      var empty0 = document.createElement('div');
      empty0.className = 'search-empty';
      empty0.textContent = 'No tools available';
      resultsWrap.appendChild(empty0);
    }
  } else {
    var matched = [];
    TPW_IDX.forEach(function(it){
      var sc = tpwScore(it, ql, qTokens);
      if (sc > 0) matched.push({it:it, score:sc});
    });
    matched.sort(function(a, b){ return b.score - a.score; });
    if (!matched.length) {
      var empty = document.createElement('div');
      empty.className = 'search-empty';
      empty.textContent = 'No tools found for "' + q + '"';
      resultsWrap.appendChild(empty);
    } else {
      var max = Math.min(matched.length, 8);
      contextIt = matched[0].it;
      for (var i = 0; i < max; i++){ resultsWrap.appendChild(tpwRenderSearchItem(matched[i].it, q, dd)); }
    }
  }
  dd.appendChild(resultsWrap);

  if (contextIt) {
    var related = TPW_IDX.filter(function(it){ return it.cat === contextIt.cat && it.href !== contextIt.href; }).slice(0, 3);
    if (related.length) {
      var relatedWrap = document.createElement('div'); relatedWrap.className = 'search-related';
      var relatedTitle = document.createElement('div'); relatedTitle.className = 'search-related-title';
      relatedTitle.textContent = 'More from ' + contextIt.cat;
      var relatedLinks = document.createElement('div'); relatedLinks.className = 'search-related-links';
      related.forEach(function(it){
        var link = document.createElement('a'); link.className = 'search-related-link'; link.href = it.href;
        link.textContent = it.name; link.addEventListener('click', function(){ tpwAddRecent(it.name, it.href); });
        relatedLinks.appendChild(link);
      });
      relatedWrap.appendChild(relatedTitle); relatedWrap.appendChild(relatedLinks); dd.appendChild(relatedWrap);
    }
  }

  if (q) {
    var foot = document.createElement('div'); foot.className = 'search-foot';
    var fa = document.createElement('a'); fa.href = '/search?q=' + encodeURIComponent(q);
    fa.innerHTML = '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><circle cx="11" cy="11" r="7"/><path d="m20 20-3.5-3.5"/></svg> Search site for "' + tpwEscapeHtml(q) + '"';
    foot.appendChild(fa);
    dd.appendChild(foot);
  }
  dd.classList.add('show');
  tpwBindDropdownClicks(dd);
}
function tpwBindDropdownClicks(dd){
  dd.querySelectorAll('.search-item').forEach(function(item){
    var name = item.getAttribute('data-name');
    item.addEventListener('click', function(){
      tpwAddRecent(name, item.href);
      var ab = document.getElementById('searchArrowBtn'); if (ab) ab.classList.remove('open');
      dd.classList.remove('show');
      var inp = dd._tpwInput; if (inp) { inp.value = ''; inp._tpwActive = -1; }
    });
  });
}
function bindSearchBar(){
  var desktopInput = document.getElementById('toolSearch');
  var mobileInput = document.getElementById('mobileToolSearch');
  var desktopDropdown = document.getElementById('searchDropdown');
  var mobileDropdown = document.getElementById('mobileSearchDropdown');

  var closeArrow = function(){ var ab = document.getElementById('searchArrowBtn'); if (ab) ab.classList.remove('open'); };

  var runSearch = function(value, inputEl, dropdownEl){
    filterTools(value || '');
    if (dropdownEl) { dropdownEl._tpwInput = inputEl; renderSearchDropdown(dropdownEl, inputEl, (value || '').trim()); }
    if (inputEl) inputEl._tpwActive = -1;
    if (dropdownEl && !dropdownEl.classList.contains('show')) closeArrow();
  };

  var bindInput = function(inputEl, dropdownEl) {
    if (!inputEl) return;
    inputEl._tpwCat = 'all';
    inputEl._tpwActive = -1;

    var handler = function(event){ runSearch(event.target.value, inputEl, dropdownEl); };
    inputEl.removeEventListener('input', inputEl._tpwSearchHandler);
    inputEl._tpwSearchHandler = handler;
    inputEl.addEventListener('input', handler);

    inputEl.addEventListener('focus', function(){
      dropdownEl._tpwInput = inputEl;
      renderSearchDropdown(dropdownEl, inputEl, inputEl.value.trim());
      inputEl._tpwActive = -1;
      closeArrow();
    });

    inputEl.addEventListener('keydown', function(event){
      var dd = dropdownEl;
      if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
        event.preventDefault();
        var items = (dd && dd._tpwItems) ? dd._tpwItems : [];
        if (!items.length) {
          if (!dd.classList.contains('show')) { renderSearchDropdown(dd, inputEl, '', true); var ab = document.getElementById('searchArrowBtn'); if (ab) ab.classList.add('open'); }
          return;
        }
        var cur = typeof inputEl._tpwActive === 'number' ? inputEl._tpwActive : -1;
        if (event.key === 'ArrowDown') cur = (cur + 1 >= items.length) ? 0 : cur + 1;
        else cur = (cur - 1 < 0) ? items.length - 1 : cur - 1;
        inputEl._tpwActive = cur;
        dd.querySelectorAll('.search-item').forEach(function(el, idx){
          el.classList.toggle('active', idx === cur);
          el.setAttribute('aria-selected', String(idx === cur));
          if (idx === cur) el.scrollIntoView({block:'nearest'});
        });
        return;
      }
      if (event.key === 'Escape') {
        inputEl.value = '';
        runSearch('', inputEl, dd);
        if (dd) dd.classList.remove('show');
        inputEl.blur();
      } else if (event.key === 'Enter') {
        var idx = inputEl._tpwActive;
        if (dd && dd._tpwItems && idx >= 0 && dd._tpwItems[idx]) {
          event.preventDefault();
          var it = dd._tpwItems[idx];
          tpwAddRecent(it.name, it.href);
          closeArrow();
          window.location.href = it.href;
          return;
        }
        var tpwQ = (inputEl.value || '').trim();
        if (tpwQ) {
          event.preventDefault();
          window.location.href = '/search?q=' + encodeURIComponent(tpwQ);
        }
      }
    });
  };

  bindInput(desktopInput, desktopDropdown);
  bindInput(mobileInput, mobileDropdown);

  var arrowBtn = document.getElementById('searchArrowBtn');
  if (arrowBtn) {
    arrowBtn.addEventListener('mousedown', function(e){
      e.preventDefault();
      var dd = desktopDropdown;
      if (dd.classList.contains('show')) {
        dd.classList.remove('show');
        desktopInput._tpwActive = -1;
        arrowBtn.classList.remove('open');
      } else {
        renderSearchDropdown(dd, desktopInput, '', true);
        desktopInput._tpwActive = -1;
        arrowBtn.classList.add('open');
        desktopInput.focus();
      }
    });
  }
}
function applyThemeState(theme){
  var html = document.documentElement;
  var btn = document.querySelector('.theme-toggle');
  var nextTheme = theme || html.getAttribute('data-theme') || 'light';
  html.setAttribute('data-theme', nextTheme);
  var themeMeta = document.querySelector('meta[name="theme-color"]');
  if (themeMeta) themeMeta.setAttribute('content', nextTheme === 'dark' ? '#0B1220' : '#2563EB');
  if (btn) {
    btn.setAttribute('aria-pressed', nextTheme === 'dark' ? 'true' : 'false');
    btn.title = nextTheme === 'dark' ? 'Switch to light mode' : 'Switch to dark mode';
  }
}
function heroRunSearch(event){
  if (event) event.preventDefault();
  var input = document.getElementById('heroToolSearch');
  var q = input ? (input.value || '').trim() : '';
  var desktop = document.getElementById('toolSearch');
  if (desktop) desktop.value = q;
  filterTools(q);
  scrollToThemeTarget('all-tools',false);
  return false;
}
function heroGoCategory(target){
  var pill = document.querySelector('.cat-pill[data-cat="' + target + '"]');
  if (pill) { selectCategory(target,pill); return; }
  scrollToThemeTarget('sec-' + target,false);
}
function toggleTheme(){
  var html = document.documentElement;
  var next = html.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
  applyThemeState(next);
  try { localStorage.setItem('tpw-theme', next); } catch(e){}
}
function closeMobileSearch(){
  var btn = document.getElementById('searchToggleBtn');
  var mobileWrap = document.getElementById('mobileSearchWrap');
  var desktopSearch = document.getElementById('headerSearch');
  var mobileDropdown = document.getElementById('mobileSearchDropdown');
  var dropdown = document.getElementById('searchDropdown');
  if (btn) {
    btn.classList.remove('active');
    btn.setAttribute('aria-expanded', 'false');
  }
  if (mobileWrap) mobileWrap.classList.remove('open');
  if (desktopSearch) desktopSearch.classList.remove('open');
  if (mobileDropdown) mobileDropdown.classList.remove('show');
  if (dropdown) dropdown.classList.remove('show');
}
function closeMobileMenu(){
  var nav = document.getElementById('mainNav');
  var btn = document.querySelector('.hamburger');
  var backdrop = document.getElementById('mobile-menu-backdrop');
  if (nav) nav.classList.remove('open');
  if (btn) {
    btn.classList.remove('is-open');
    btn.setAttribute('aria-expanded', 'false');
    btn.innerHTML = '&#9776;';
  }
  if (backdrop) backdrop.classList.remove('open');
  document.body.style.overflow = '';
}
function toggleMobileSearch(){
  var btn = document.getElementById('searchToggleBtn');
  if (!btn) return;
  var shouldOpen = !btn.classList.contains('active');
  if (shouldOpen) {
    closeMobileMenu();
  }
  btn.classList.toggle('active', shouldOpen);
  btn.setAttribute('aria-expanded', String(shouldOpen));
  var mobileWrap = document.getElementById('mobileSearchWrap');
  var desktopSearch = document.getElementById('headerSearch');
  if (window.innerWidth <= 1200) {
    if (mobileWrap) {
      mobileWrap.classList.toggle('open', shouldOpen);
      if (shouldOpen) {
        var mobileInput = document.getElementById('mobileToolSearch');
        if (mobileInput) setTimeout(function(){ mobileInput.focus(); }, 60);
      } else {
        var mobileDropdown = document.getElementById('mobileSearchDropdown');
        if (mobileDropdown) mobileDropdown.classList.remove('show');
      }
    }
    if (desktopSearch) {
      desktopSearch.classList.remove('open');
      var dropdown = document.getElementById('searchDropdown');
      if (dropdown) dropdown.classList.remove('show');
    }
    return;
  }
  if (desktopSearch) {
    desktopSearch.classList.toggle('open', shouldOpen);
    if (shouldOpen) {
      var input = document.getElementById('toolSearch');
      if (input) setTimeout(function(){ input.focus(); }, 60);
    } else {
      var dropdown2 = document.getElementById('searchDropdown');
      if (dropdown2) dropdown2.classList.remove('show');
    }
  }
  if (mobileWrap) mobileWrap.classList.remove('open');
}
function toggleMobileMenu(){
  var nav = document.getElementById('mainNav');
  var btn = document.querySelector('.hamburger');
  if (!nav || !btn) return;
  var isOpen = !nav.classList.contains('open');
  if (isOpen) {
    closeMobileSearch();
  }
  nav.classList.toggle('open', isOpen);
  btn.classList.toggle('is-open', isOpen);
  btn.setAttribute('aria-expanded', String(isOpen));
  btn.innerHTML = isOpen ? '&#10005;' : '&#9776;';
  document.body.style.overflow = '';
}
window.addEventListener('click', function(event){
  var nav = document.getElementById('mainNav');
  var btn = document.querySelector('.hamburger');
  var searchBtn = document.getElementById('searchToggleBtn');
  var mobileSearchWrap = document.getElementById('mobileSearchWrap');
  var desktopSearch = document.getElementById('headerSearch');
  var desktopDropdown = document.getElementById('searchDropdown');
  var mobileDropdown = document.getElementById('mobileSearchDropdown');
  var backdrop = document.getElementById('mobile-menu-backdrop');

  if (nav && btn && !nav.contains(event.target) && !btn.contains(event.target) && nav.classList.contains('open')) {
    closeMobileMenu();
  }
  if (searchBtn && mobileSearchWrap && mobileSearchWrap.classList.contains('open') &&
      !mobileSearchWrap.contains(event.target) && !searchBtn.contains(event.target)) {
    closeMobileSearch();
  }
  if (searchBtn && desktopSearch && desktopSearch.classList.contains('open') &&
      !desktopSearch.contains(event.target) && !searchBtn.contains(event.target)) {
    closeMobileSearch();
  }
  if (desktopDropdown && desktopDropdown.classList.contains('show') && desktopSearch && !desktopSearch.contains(event.target)) {
    desktopDropdown.classList.remove('show');
    var arrow = document.getElementById('searchArrowBtn'); if (arrow) arrow.classList.remove('open');
  }
  if (mobileDropdown && mobileDropdown.classList.contains('show') && mobileSearchWrap && !mobileSearchWrap.contains(event.target)) {
    mobileDropdown.classList.remove('show');
  }
  if (backdrop && backdrop.contains(event.target) && backdrop.classList.contains('open')) {
    closeMobileMenu();
  }
});
window.addEventListener('resize', function(){
  updateCatNav();
  if (window.innerWidth > 1200) {
    closeMobileMenu();
    closeMobileSearch();
    if (document.getElementById('mainNav')) document.getElementById('mainNav').classList.remove('open');
  }
});
function initializeThemeAndSearch(){
  var pageRoot = document.documentElement;
  if (pageRoot) {
    var isStaticPage = document.querySelector('.about-content,.contact-content,.privacy-content,.terms-content');
    var isToolPage = document.querySelector('.tool-layout,.tool-crumbs-wrap');
    pageRoot.classList.toggle('tpw-static-page', !!isStaticPage);
    pageRoot.classList.toggle('tpw-tool-page', !isStaticPage && !!isToolPage);
  }
  var headerLogoImage = document.querySelector('.tpw-logo-slot img.logo-image');
  var footerLogoImage = document.getElementById('footerLogoImage');
  if (headerLogoImage && footerLogoImage) footerLogoImage.src = headerLogoImage.src;
  if (footerLogoImage) {
    var footerFallback = document.querySelectorAll('.footer-logo-fallback');
    var showFooterLogo = function(){
      footerLogoImage.alt = footerLogoImage.alt || 'Tools Pro Web footer logo';
      footerLogoImage.style.display='block';
      footerFallback.forEach(function(el){el.style.display='none';});
    };
    var showFooterFallback = function(){footerLogoImage.style.display='none';footerFallback.forEach(function(el){el.style.display='';});};
    if (footerLogoImage.complete) {
      if (footerLogoImage.naturalWidth) showFooterLogo(); else showFooterFallback();
    } else {
      footerLogoImage.addEventListener('load',showFooterLogo,{once:true});
      footerLogoImage.addEventListener('error',showFooterFallback,{once:true});
    }
  }
  var saved = null;
  try { saved = localStorage.getItem('tpw-theme'); } catch(e){}
  var prefersDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
  var theme = saved || (prefersDark ? 'dark' : 'light');
  applyThemeState(theme);
  var toolCount = document.querySelector('.stat-num[data-count="230"]');
  if (toolCount && window.TPW_FLAT_TOOLS) toolCount.setAttribute('data-count', String(window.TPW_FLAT_TOOLS.length));
  var categoryCount = document.querySelector('.stat-num[data-count="10"]');
  if (categoryCount && typeof SECTIONS !== 'undefined') categoryCount.setAttribute('data-count', String(SECTIONS.length));
  var year = document.getElementById('copyrightYear');
  if (year) year.textContent = String(new Date().getFullYear());
  bindSearchBar();
  var categoryRail = document.getElementById('catGrid');
  if (categoryRail) {
    updateCatNav();
    categoryRail.addEventListener('scroll', updateCatNav, {passive:true});
  }
  var headerEl = document.querySelector('.tpw-header');
  if (headerEl) {
    var onScroll = function(){
      headerEl.classList.toggle('scrolled', window.scrollY > 8);
    };
    onScroll();
    window.addEventListener('scroll', onScroll, { passive: true });
  }
}
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initializeThemeAndSearch);
} else {
  initializeThemeAndSearch();
}
window.addEventListener('scroll', function(){
  var b = document.getElementById('toTop');
  if (b) b.classList.toggle('show', window.scrollY > 400);
});

/* Animated stat counters */
(function(){
  var nums = document.querySelectorAll('.stat-num[data-count]');
  if (!nums.length) return;
  function animate(el){
    var target = parseInt(el.getAttribute('data-count'), 10);
    var prefix = el.getAttribute('data-prefix') || '';
    var suffix = el.getAttribute('data-suffix') || '';
    var dur = 1600, start = null;
    function step(ts){
      if (!start) start = ts;
      var p = Math.min((ts - start) / dur, 1);
      var eased = 1 - Math.pow(1 - p, 3);
      el.textContent = prefix + Math.round(target * eased) + suffix;
      if (p < 1) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  }
  if ('IntersectionObserver' in window) {
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if (e.isIntersecting) { animate(e.target); io.unobserve(e.target); }
      });
    }, {threshold: 0.4});
    nums.forEach(function(n){ io.observe(n); });
  } else {
    nums.forEach(animate);
  }
})();

/* Hero slider */
(function(){
  var track = document.getElementById('hsTrack');
  if (!track) return;
  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var dotsWrap = document.getElementById('hsDots');
  var wrap = track.parentElement;
  var prevBtn = document.getElementById('hsPrev');
  var nextBtn = document.getElementById('hsNext');
  var total = track.children.length;
  var cur = 0, timer = null, startX = null;
  Array.prototype.forEach.call(track.children, function(slide){
    var categoryId = slide.getAttribute('data-category') || 'all';
    var copy = slide.firstElementChild;
    var art = slide.querySelector('.hs-art');
    if (copy) {
      copy.classList.add('hs-copy');
      var categoryLabel = 'All Tools';
      if (categoryId !== 'all' && typeof SECTIONS !== 'undefined') {
        for (var labelIndex = 0; labelIndex < SECTIONS.length; labelIndex++) {
          if (SECTIONS[labelIndex].id === categoryId) { categoryLabel = SECTIONS[labelIndex].name; break; }
        }
      }
      var kicker = document.createElement('span'); kicker.className = 'hs-kicker';
      kicker.textContent = categoryId === 'all' ? 'Complete Toolkit' : categoryLabel;
      copy.insertBefore(kicker, copy.firstChild);
      var sourceTools = [];
      if (categoryId === 'all') sourceTools = (window.TPW_FLAT_TOOLS || []).slice(0, 3);
      else if (typeof SECTIONS !== 'undefined') {
        for (var s = 0; s < SECTIONS.length; s++) {
          if (SECTIONS[s].id === categoryId) {
            sourceTools = SECTIONS[s].tools.slice(0, 3).map(function(t){ return {name:t[0],href:t[1]}; });
            break;
          }
        }
      }
      if (sourceTools.length) {
        var preview = document.createElement('div'); preview.className = 'hs-preview';
        sourceTools.forEach(function(tool){
          var link = document.createElement('a'); link.href = tool.href; link.textContent = tool.name;
          preview.appendChild(link);
        });
        var primary = copy.querySelector('.btn'); copy.insertBefore(preview, primary);
      }
      if (art) {
        var count = document.createElement('span'); count.className = 'hs-count';
        var countValue = categoryId === 'all' ? (window.TPW_FLAT_TOOLS || []).length : sourceTools.length;
        if (categoryId !== 'all' && typeof SECTIONS !== 'undefined') {
          for (var c = 0; c < SECTIONS.length; c++) if (SECTIONS[c].id === categoryId) countValue = SECTIONS[c].tools.length;
        }
        count.textContent = countValue + (countValue === 1 ? ' tool' : ' tools'); art.appendChild(count);
      }
    }
  });
  for (var i = 0; i < total; i++) {
    var b = document.createElement('button');
    b.className = 'hs-dot' + (i === 0 ? ' active' : '');
    var slideName = track.children[i].getAttribute('data-category') || ('Slide ' + (i + 1));
    b.setAttribute('aria-label', 'Show ' + slideName + ' tools');
    (function(idx){ b.onclick = function(){ go(idx); reset(); }; })(i);
    dotsWrap.appendChild(b);
  }
  function go(n){
    cur = (n + total) % total;
    track.style.transform = 'translateX(-' + (cur * 100) + '%)';
    var ds = dotsWrap.children;
    for (var i = 0; i < ds.length; i++) {
      ds[i].classList.toggle('active', i === cur);
      ds[i].setAttribute('aria-current', i === cur ? 'true' : 'false');
      track.children[i].setAttribute('aria-hidden', i === cur ? 'false' : 'true');
      var slideLinks = track.children[i].querySelectorAll('a');
      slideLinks.forEach(function(link){ link.setAttribute('tabindex', i === cur ? '0' : '-1'); });
    }
  }
  function next(){ go(cur + 1); }
  function reset(){ clearInterval(timer); if (!reduceMotion) timer = setInterval(next, 5000); }
  go(0);
  reset();
  if (prevBtn) prevBtn.addEventListener('click', function(){ go(cur - 1); reset(); });
  if (nextBtn) nextBtn.addEventListener('click', function(){ go(cur + 1); reset(); });
  if (wrap) {
    wrap.addEventListener('mouseenter', function(){ clearInterval(timer); });
    wrap.addEventListener('mouseleave', reset);
    wrap.addEventListener('focusin', function(){ clearInterval(timer); });
    wrap.addEventListener('focusout', reset);
    wrap.addEventListener('pointerdown', function(e){ if (e.pointerType !== 'mouse') startX = e.clientX; });
    wrap.addEventListener('pointerup', function(e){
      if (startX === null) return;
      var distance = e.clientX - startX; startX = null;
      if (Math.abs(distance) > 42) { go(cur + (distance < 0 ? 1 : -1)); reset(); }
    });
    wrap.addEventListener('pointercancel', function(){ startX = null; });
  }
})();
document.querySelectorAll('a[href*="#"]').forEach(function(a){
  a.addEventListener('click',function(e){
    var href = a.getAttribute('href') || '';
    var hashAt = href.indexOf('#');
    var id = hashAt >= 0 ? decodeURIComponent(href.slice(hashAt + 1)) : '';
    if (id && document.getElementById(id)) {
      e.preventDefault();
      scrollToThemeTarget(id,true);
    }
  });
});
var menu = document.getElementById('mainNav');
if (menu) menu.querySelectorAll('a').forEach(function(a){
  a.addEventListener('click', function(e){
    menu.classList.remove('open');
    var backdrop = document.getElementById('mobile-menu-backdrop');
    if (backdrop) backdrop.classList.remove('open');
    document.body.style.overflow = '';
    var btn = document.querySelector('.hamburger');
    if (btn) { btn.classList.remove('is-open'); btn.setAttribute('aria-expanded','false'); btn.innerHTML = '&#9776;'; }
  });
});
if (window.location.hash) {
  setTimeout(function() {
    scrollToThemeTarget(decodeURIComponent(window.location.hash.slice(1)),false);
  }, 400);
}
